import json, struct, numpy as np
P='/workspace/model/model.safetensors-00001-of-00001.safetensors'
_f=open(P,'rb'); _n=struct.unpack('<Q',_f.read(8))[0]; _h=json.loads(_f.read(_n)); _base=8+_n
def bf16_to_f32(buf):
    u=np.frombuffer(buf,dtype=np.uint16).astype(np.uint32)<<16
