    elif m['dtype']=='F32': a=np.frombuffer(buf,dtype=np.float32)
    else: raise ValueError(m['dtype'])
    return a.reshape(m['shape']).copy()
def LW(i, sub): return W(f'model.language_model.layers.{i}.{sub}.weight')
