import numpy as np, json
def load(k):
    return np.load(f'X{k}.npy'), np.load(f'H{k}.npy'), json.load(open(f'M{k}.json'))
def ridge(X, y, lam, w=None):
    if w is None: w=np.ones(len(y),dtype=np.float32)
    Xw=X*w[:,None]
    G=(Xw.T@X).astype(np.float64); G[np.diag_indices_from(G)]+=lam
    return np.linalg.solve(G, (Xw.T@y).astype(np.float64)).astype(np.float32)
def report(name, s, y, meta, show=8):
    pos=s[y==1]; neg=s[y==0]
    print(f'{name}: pos n={len(pos)} mean={pos.mean():.3f} min={pos.min():.3f} p10={np.percentile(pos,10):.3f} | neg n={len(neg)} mean={neg.mean():.4f} std={neg.std():.4f} p99={np.percentile(neg,99):.3f} p99.9={np.percentile(neg,99.9):.3f} max={neg.max():.3f}')
    idx=np.where(y==0)[0]; top=idx[np.argsort(-s[idx])[:show]]
    for i in top:
        m=meta[i]; print('    FP', round(float(s[i]),3), (m['k'],m['item'],m['i']), repr(m['tok']), '->', repr(m['nxt']), 'in_code' if m['in_code'] else 'text', m['lang'])
    idx=np.where(y==1)[0]; low=idx[np.argsort(s[idx])[:show]]
    for i in low:
        m=meta[i]; print('    FN', round(float(s[i]),3), (m['k'],m['item'],m['i']), repr(m['tok']), '->', repr(m['nxt']), 'nblock',m['nblock'])
